ik as (select i.unit_price, i.weight_kg, i.stock_qty, upper(regexp_replace(coalesce(i.item_code, ''), '[[:space:]()（）]', '', 'g')) || '|' || upper(regexp_replace(i.description, '[[:space:]()（）]', '', 'g'))
           || case when trim(coalesce(i.note, '')) ~* '^(concentric|eccentric)$' then '|' || upper(trim(i.note)) else '' end as key from public.inventory_items i),
ins as (
  insert into public.inventory_items (item_code, description, weight_kg, unit_price, stock_qty, loading_charges, actual_weight, note, created_at)
  select s.item_code, s.description, s.weight_kg, s.unit_price, s.stock_qty, s.loading_charges, s.actual_weight, s.note, now() + make_interval(secs => s.ord / 1000.0)
  from s where not exists (select 1 from ik where ik.key = s.key)
  order by s.ord
  returning id
)
select (select count(*) from ins) as items_added;
